// applyFaults wraps each web-exposed Manager in its fault wrapper when url, the scenario host's
// address, is set. Unset, it returns managers unchanged under every profile; set under any profile
// but local, it refuses, so a deployed binary cannot be told to take faults from a test host.
func applyFaults(profile, url string, managers WebManagers) (WebManagers, error) {
	if url == "" {
		return managers, nil
	}
	if profile != "local" {
		return managers, fmt.Errorf("a scenario host address is set under profile %q: fault injection is a local-profile test instrument, so the process refuses to start", profile)
	}
	take := faultTaker(url)
	managers.BillingManager = faultBillingManager{inner: managers.BillingManager, take: take}
	managers.DeliveryManager = faultDeliveryManager{inner: managers.DeliveryManager, take: take}
	managers.OperationsManager = faultOperationsManager{inner: managers.OperationsManager, take: take}
	return managers, nil
}
